// FROZEN fixture. It represents the Node09 FINALIZE output of PR #12
// (WF-Research-06-09). It is the Node10 boundary input. A live wiring replaces
// this node after both workflows are merged. It carries the IS selection only.
// It holds no OOS result.
const runKey = 'b7c1e0d4a9f24c8fb3e6d5a10c72f984';
const runId = '3ad9f0c4b1e2487fa5c6d87013be92f4';
const analysisHash = 'a7d2f6b8c4e0193d5a6f7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2e3f4a5b6c7d8e';
const noteRef = 'quant/research-loop/' + runKey + '.md';
const analysis = {
  source_run_key: runKey,
  source_run_id: runId,
  period_basis: 'IS',
  previous_hypothesis_ref: null,
  expectation_vs_actual: [
    { condition: 'drawdown band', expectation: 'max_drawdown <= 0.20', actual: 0.18, verdict: 'MET' }
  ],
  lessons: ['The 20/10 breakout keeps the drawdown inside the declared band.'],
  worth_retesting: false,
  analysis_ref: 'hermes-analysis://research-loop/' + runKey + '/round-0',
  analysis_hash: analysisHash,
  proposal: { source_run_key: runKey, change_set: null }
};
return [{
  json: {
    payload_kind: 'node09_finalize',
    finalize: {
      run_key: runKey,
      run_id: runId,
      round_index: 0,
      period_basis: 'IS',
      metrics_summary: { sharpe: 1.12, max_drawdown: 0.18, trades: 214 },
      metrics_ref: 'mlflow://qlib/runs/' + runKey + '/metrics',
      evidence_refs: {
        run_manifest: 'mlflow://qlib/runs/' + runKey + '/manifest.json',
        analysis_source: 'hermes-analysis://research-loop/' + runKey + '/round-0'
      },
      completed_runs: [{ round_index: 0, run_key: runKey, status: 'IS_SUCCESS' }],
      analysis: analysis,
      wiki_ack: { status: 'ACK', action: 'CREATED', note_ref: noteRef, run_key: runKey, analysis_hash: analysisHash },
      change_set: null,
      route: 'FINALIZE',
      decision: {
        selected_run_key: runKey,
        selected_run_id: runId,
        selected_round_index: 0,
        selected_analysis_ref: analysis.analysis_ref,
        selected_analysis_hash: analysisHash,
        selected_wiki_note_ref: noteRef,
        period_basis: 'IS',
        finalize_reason: 'WORTH_RETESTING_FALSE'
      }
    }
  }
}];

// FROZEN fixture. It represents the existing upstream readback of the frozen IS
// run manifest: identity, config, data, window and cost snapshots. A live
// readback over the existing 01-05 path replaces this node. It carries no OOS
// result. The OOS window and the OOS run key are predefined here.
return [{
  json: {
    payload_kind: 'frozen_is_snapshot',
    snapshot: {
      readback_ref: 'mlflow://qlib/runs/b7c1e0d4a9f24c8fb3e6d5a10c72f984/manifest.json',
      run_key: 'b7c1e0d4a9f24c8fb3e6d5a10c72f984',
      run_id: '3ad9f0c4b1e2487fa5c6d87013be92f4',
      source: {
        family_id: 'donchian-breakout',
        family_name: 'Donchian breakout',
        source_strategy_id: 'alpha-donchian-20-10',
        source_strategy_version: 'v1',
        source_repository_url: 'https://github.com/HCH725/alpha-strategy-research',
        source_strategy_path: 'strategies/donchian-20-10.md',
        source_git_commit: '9a1b2c3d4e5f60718293a4b5c6d7e8f901234567',
        change_note: 'Exit window tightened to 15 after the Node06-09 IS loop.'
      },
      strategy_sha: '1f0a2b3c4d5e6f708192a3b4c5d6e7f8091a2b3c4d5e6f708192a3b4c5d6e7f8',
      frozen_version_sha: '2a1b3c4d5e6f70819a2b3c4d5e6f708192a3b4c5d6e7f8091a2b3c4d5e6f7081',
      effective_config_hash: '3b2c4d5e6f708192a3b4c5d6e7f8091a2b3c4d5e6f708192a3b4c5d6e7f8091a',
      config_snapshot: {
        uri: 'mlflow://qlib/runs/b7c1e0d4a9f24c8fb3e6d5a10c72f984/artifacts/frozen_config.json',
        sha256: '4c3d5e6f708192a3b4c5d6e7f8091a2b3c4d5e6f708192a3b4c5d6e7f8091a2b'
      },
      data_snapshot: {
        uri: 'research-data://klines/2022-01-01_2025-06-30/day',
        sha256: '5d4e6f708192a3b4c5d6e7f8091a2b3c4d5e6f708192a3b4c5d6e7f8091a2b3c',
        dataset_version: 'kline-day-v3'
      },
      is_window: { start_utc: '2022-01-01', end_utc: '2024-12-31', window_hash: '6e5f708192a3b4c5d6e7f8091a2b3c4d5e6f708192a3b4c5d6e7f8091a2b3c4d' },
      oos_plan: {
        start_utc: '2025-01-01',
        end_utc: '2025-06-30',
        window_hash: '7f608192a3b4c5d6e7f8091a2b3c4d5e6f708192a3b4c5d6e7f8091a2b3c4d5e',
        oos_run_key: 'c8d9e0f1a2b3c4d5e6f708192a3b4c5d'
      },
      cost_model: {
        uri: 'mlflow://qlib/cost-models/futures-taker-v2.json',
        sha256: '8091a2b3c4d5e6f708192a3b4c5d6e7f8091a2b3c4d5e6f708192a3b4c5d6e7f',
        fee_rate_bps: 4,
        slippage_bps: 2,
        funding_model: 'modelled_v2'
      },
      runtime: { qlib_engine_version: 'pyqlib-0.9.7', runtime_git_commit_or_image: 'qlib-arm64-container:2026-10-01' },
      research_refs: {
        coverage_42cell: {
          planned_ref: 'research-nav://42cell/donchian/planned.json',
          tested_ref: 'research-nav://42cell/donchian/tested.json',
          excluded_ref: 'research-nav://42cell/donchian/excluded.json'
        },
        wiki_refs: ['quant/research-loop/b7c1e0d4a9f24c8fb3e6d5a10c72f984.md']
      },
      limitations: [
        'Funding uses the frozen modelled series. It is not live-verified.',
        'The 42-cell coverage excludes the trailing-stop family by plan.'
      ]
    }
  }
}];

// Node10 freezes the IS-selected identity, config, data, window and cost
// snapshots. It emits the single one-time OOS request. No LLM runs here. No OOS
// result is read. The version decision uses the IS round series only.
const inItems = $input.all().map((entry) => entry.json);
const isText = (v) => typeof v === 'string' && v.length > 0;
const isHex = (v, n) => typeof v === 'string' && v.length === n && /^[a-f0-9]+$/.test(v);
const stop = (reason) => [{ json: { payload_kind: 'node10_review', stage: '10', route: 'NEEDS_REVIEW', reason: reason } }];
const finalizeItem = inItems.filter((row) => row && row.payload_kind === 'node09_finalize')[0];
const snapshotItem = inItems.filter((row) => row && row.payload_kind === 'frozen_is_snapshot')[0];
if (!finalizeItem) { return stop('finalize_input_missing'); }
if (!snapshotItem) { return stop('frozen_snapshot_input_missing'); }
const f = finalizeItem.finalize;
const s = snapshotItem.snapshot;
if (!f || typeof f !== 'object') { return stop('finalize_payload_missing'); }
if (!s || typeof s !== 'object') { return stop('snapshot_payload_missing'); }
if (f.route !== 'FINALIZE') { return stop('finalize_route_not_finalize'); }
const d = f.decision || {};
if (d.period_basis !== 'IS') { return stop('selection_basis_not_is'); }
if (!isHex(d.selected_run_key, 32)) { return stop('selected_run_key_bad_shape'); }
if (!isHex(d.selected_run_id, 32)) { return stop('selected_run_id_bad_shape'); }
if (!isHex(d.selected_analysis_hash, 64)) { return stop('selected_analysis_hash_bad_shape'); }
if (!isText(d.selected_analysis_ref) || !isText(d.selected_wiki_note_ref)) { return stop('selected_refs_missing'); }
const rounds = Array.isArray(f.completed_runs) ? f.completed_runs : [];
if (rounds.length === 0) { return stop('completed_runs_empty'); }
for (let i = 0; i < rounds.length; i += 1) {
  const row = rounds[i];
  if (!row || row.round_index !== i) { return stop('round_series_not_contiguous'); }
  if (row.status !== 'IS_SUCCESS') { return stop('round_series_not_is_success'); }
  if (!isHex(row.run_key, 32)) { return stop('round_run_key_bad_shape'); }
}
const head = rounds[rounds.length - 1];
if (head.run_key !== d.selected_run_key) { return stop('selected_run_not_is_head'); }
if (head.round_index !== d.selected_round_index) { return stop('selected_round_mismatch'); }
if (f.analysis && f.analysis.analysis_hash !== d.selected_analysis_hash) { return stop('selected_analysis_hash_mismatch'); }
if (f.wiki_ack && f.wiki_ack.note_ref !== d.selected_wiki_note_ref) { return stop('selected_wiki_note_mismatch'); }

// The frozen snapshot must describe the same selected IS run.
if (s.run_key !== d.selected_run_key || s.run_id !== d.selected_run_id) { return stop('snapshot_identity_mismatch'); }
if (!isHex(s.strategy_sha, 64)) { return stop('strategy_sha_bad_shape'); }
if (!isHex(s.frozen_version_sha, 64)) { return stop('frozen_version_sha_bad_shape'); }
if (!isHex(s.effective_config_hash, 64)) { return stop('effective_config_hash_bad_shape'); }
if (!s.config_snapshot || !isHex(s.config_snapshot.sha256, 64) || !isText(s.config_snapshot.uri)) { return stop('config_snapshot_incomplete'); }
if (!s.data_snapshot || !isHex(s.data_snapshot.sha256, 64) || !isText(s.data_snapshot.uri)) { return stop('data_snapshot_incomplete'); }
if (!s.cost_model || !isHex(s.cost_model.sha256, 64) || !isText(s.cost_model.uri)) { return stop('cost_model_incomplete'); }
if (!s.runtime || !isText(s.runtime.qlib_engine_version)) { return stop('runtime_snapshot_incomplete'); }
if (!s.source || !isText(s.source.source_strategy_id) || !/^[a-f0-9]{40}$/.test(String(s.source.source_git_commit || ''))) { return stop('source_provenance_incomplete'); }
const windowOk = (w) => w && isText(w.start_utc) && isText(w.end_utc) && isHex(w.window_hash, 64);
if (!windowOk(s.is_window)) { return stop('is_window_snapshot_incomplete'); }
if (!windowOk(s.oos_plan)) { return stop('oos_window_not_predefined'); }
if (!isHex(s.oos_plan.oos_run_key, 32)) { return stop('oos_run_key_bad_shape'); }
const stamp = (v) => Date.parse(v);
if (!(stamp(s.is_window.start_utc) < stamp(s.is_window.end_utc))) { return stop('is_window_bad_period'); }
if (!(stamp(s.oos_plan.start_utc) > stamp(s.is_window.end_utc))) { return stop('oos_window_overlaps_is'); }
if (s.oos_plan.window_hash === s.is_window.window_hash) { return stop('oos_window_hash_reused'); }
if (s.oos_plan.oos_run_key === d.selected_run_key) { return stop('oos_run_key_not_unique'); }
for (const row of rounds) {
  if (row.run_key === s.oos_plan.oos_run_key) { return stop('oos_run_key_not_unique'); }
}
// No OOS result may influence the selection.
const blob = JSON.stringify(f) + JSON.stringify(s);
if (/"(oos_metrics|oos_result|oos_equity|oos_trades|oos_returns|oos_fills)"/.test(blob)) { return stop('oos_result_material_in_input'); }

const identity = {
  best_is_run_key: d.selected_run_key,
  best_is_run_id: d.selected_run_id,
  round_index: d.selected_round_index,
  analysis_ref: d.selected_analysis_ref,
  analysis_hash: d.selected_analysis_hash,
  wiki_note_ref: d.selected_wiki_note_ref,
  finalize_reason: d.finalize_reason
};
const freeze = {
  frozen_version_sha: s.frozen_version_sha,
  effective_config_hash: s.effective_config_hash,
  strategy_sha: s.strategy_sha,
  source: s.source,
  config_snapshot: s.config_snapshot,
  data_snapshot: s.data_snapshot,
  is_window: s.is_window,
  oos_plan: s.oos_plan,
  cost_model: s.cost_model,
  runtime: s.runtime,
  research_refs: s.research_refs,
  limitations: s.limitations
};
const oos_request = {
  best_is_run_key: d.selected_run_key,
  frozen_version_sha: s.frozen_version_sha,
  effective_config_hash: s.effective_config_hash,
  period_basis: 'OOS',
  window_hash: s.oos_plan.window_hash,
  parent_is_run_key: d.selected_run_key,
  oos_run_key: s.oos_plan.oos_run_key,
  holdout_policy: 'ONE_TIME_NO_RETUNE'
};
return [{ json: {
  payload_kind: 'oos_request',
  stage: '10',
  identity: identity,
  freeze: freeze,
  oos_request: oos_request,
  route: 'OOS_REQUEST'
} }];

// Node10 hands the one-time OOS request to this boundary. The existing 04/05
// execution is not wired here and is not modified. This fixture represents the
// OOS_READY reply of the existing 05 readback. A live readback replaces it.
const x = $input.first().json;
const request = x.oos_request;
const freeze = x.freeze;
return [{ json: Object.assign({}, x, {
  oos_ready: {
    oos_run_key: request.oos_run_key,
    oos_run_id: 'd9e0f1a2b3c4d5e6f708192a3b4c5d6e',
    period_basis: 'OOS',
    window_hash: request.window_hash,
    frozen_version_sha: request.frozen_version_sha,
    effective_config_hash: request.effective_config_hash,
    strategy_sha: freeze.strategy_sha,
    data_snapshot_sha256: freeze.data_snapshot.sha256,
    oos_attempt_index: 1,
    retune_performed: false,
    holdout_policy: request.holdout_policy,
    manifest_complete: true,
    metrics: {
      cagr_pct: 14.2,
      sharpe: 1.21,
      max_drawdown_pct: 19.0,
      max_drawdown_definition: 'peak_to_trough_net',
      trades: 128,
      net_return_pct: 14.2,
      win_rate_pct: 48.4,
      profit_factor: 1.62
    },
    evaluation_period: { start_utc: freeze.oos_plan.start_utc, end_utc: freeze.oos_plan.end_utc },
    cost_model_applied: {
      fee_rate_bps: freeze.cost_model.fee_rate_bps,
      slippage_bps: freeze.cost_model.slippage_bps,
      funding: 'modelled'
    },
    evidence_refs: {
      oos_manifest: 'mlflow://qlib/runs/' + request.oos_run_key + '/manifest.json',
      metrics: 'mlflow://qlib/runs/' + request.oos_run_key + '/metrics',
      portfolio_report: 'mlflow://qlib/runs/' + request.oos_run_key + '/portfolio_report',
      trades: 'mlflow://qlib/runs/' + request.oos_run_key + '/trades',
      equity: 'mlflow://qlib/runs/' + request.oos_run_key + '/equity'
    },
    runtime: freeze.runtime
  },
  route: 'OOS_READY'
}) }];

// Node10 re-entry gate. It validates the OOS_READY reply against the frozen
// request before Node11 evaluates. An incomplete reply or one identity mismatch
// is a review item. The workflow never sends this state back to Nodes 06-09.
const x = $input.first().json;
const isText = (v) => typeof v === 'string' && v.length > 0;
const isHex = (v, n) => typeof v === 'string' && v.length === n && /^[a-f0-9]+$/.test(v);
const stop = (reason) => [{ json: Object.assign({}, x, { route: 'NEEDS_REVIEW', reason: reason }) }];
if (x.route === 'NEEDS_REVIEW') { return [{ json: x }]; }
if (x.route !== 'OOS_READY') { return stop('oos_boundary_route_not_ready:' + x.route); }
const r = x.oos_request || {};
const o = x.oos_ready || {};
const freeze = x.freeze || {};
const missing = [];
if (!isHex(o.oos_run_key, 32)) { missing.push('oos_run_key'); }
if (!isHex(o.oos_run_id, 32)) { missing.push('oos_run_id'); }
if (!isHex(o.window_hash, 64)) { missing.push('window_hash'); }
if (!isHex(o.frozen_version_sha, 64)) { missing.push('frozen_version_sha'); }
if (!isHex(o.effective_config_hash, 64)) { missing.push('effective_config_hash'); }
if (!isHex(o.strategy_sha, 64)) { missing.push('strategy_sha'); }
if (!isHex(o.data_snapshot_sha256, 64)) { missing.push('data_snapshot_sha256'); }
if (!o.metrics || typeof o.metrics !== 'object') { missing.push('metrics'); }
if (!o.evaluation_period || !isText(o.evaluation_period.start_utc) || !isText(o.evaluation_period.end_utc)) { missing.push('evaluation_period'); }
if (!o.evidence_refs || typeof o.evidence_refs !== 'object') { missing.push('evidence_refs'); }
if (!o.cost_model_applied || typeof o.cost_model_applied !== 'object') { missing.push('cost_model_applied'); }
if (!o.runtime || typeof o.runtime !== 'object') { missing.push('runtime'); }
if (missing.length > 0) { return stop('oos_ready_incomplete:' + missing.join(',')); }
if (o.manifest_complete !== true) { return stop('oos_manifest_incomplete'); }
if (o.period_basis !== 'OOS') { return stop('oos_period_basis_mismatch'); }
if (o.oos_run_key !== r.oos_run_key) { return stop('oos_run_key_mismatch'); }
if (o.window_hash !== r.window_hash) { return stop('oos_window_hash_mismatch'); }
if (o.frozen_version_sha !== r.frozen_version_sha) { return stop('frozen_version_sha_mismatch'); }
if (o.effective_config_hash !== r.effective_config_hash) { return stop('effective_config_hash_mismatch'); }
if (o.strategy_sha !== freeze.strategy_sha) { return stop('strategy_sha_mismatch'); }
if (o.data_snapshot_sha256 !== (freeze.data_snapshot || {}).sha256) { return stop('data_snapshot_mismatch'); }
if (o.cost_model_applied.fee_rate_bps !== (freeze.cost_model || {}).fee_rate_bps) { return stop('cost_model_fee_mismatch'); }
if (o.cost_model_applied.slippage_bps !== (freeze.cost_model || {}).slippage_bps) { return stop('cost_model_slippage_mismatch'); }
if (o.oos_attempt_index !== 1) { return stop('oos_not_one_time_attempt_1'); }
if (o.retune_performed !== false) { return stop('oos_retune_forbidden'); }
if (o.holdout_policy !== 'ONE_TIME_NO_RETUNE') { return stop('oos_holdout_policy_mismatch'); }
return [{ json: Object.assign({}, x, { route: 'OOS_READY_OK' }) }];

// Boundary fixture. It represents a fresh read of the authoritative promotion
// policy: the HCH725/research-survivor README on main, plus the promotion
// identity assignment. A live read replaces this node. The workflow never
// guesses a policy. An unapproved or unreadable policy holds.
return [{ json: {
  payload_kind: 'promotion_policy',
  policy: {
    source_ref: 'https://github.com/HCH725/research-survivor/blob/384ab0df97ebaa48ddf7f1e398e347f210c57212/README.md',
    policy_version: 'qlib-promotion-policy-v1',
    approved: true,
    thresholds: { cagr_min_pct: 10, sharpe_min: 1.0 },
    evaluation_period_defined: true,
    cost_basis_defined: true,
    evaluation_unit: 'OOS window, net of declared fees and slippage',
    draft_8pct_used: false
  },
  promotion: { survivor_id: 'svr-donchian-exit15', survivor_version: 'v1' },
  route: 'POLICY_INPUT'
} }];

// Node11 is deterministic evaluation only. No LLM and no MoA run here. The
// promotion policy is injected from the authoritative input. It is never
// guessed in code. A performance shortfall is REJECT. A missing policy, cost,
// period or reproducibility evidence is HOLD.
const inItems = $input.all().map((entry) => entry.json);
const isText = (v) => typeof v === 'string' && v.length > 0;
const state = inItems.filter((row) => row && row.payload_kind === 'oos_request')[0];
const policyItem = inItems.filter((row) => row && row.payload_kind === 'promotion_policy')[0];
const stop = (route, reason) => [{ json: Object.assign({}, state || {}, { route: route, reason: reason }) }];
// No OOS state means the upstream gate already signalled a review item.
if (!state) { return []; }
if (!policyItem || !policyItem.policy) { return stop('HOLD', 'promotion_policy_input_missing'); }
const p = policyItem.policy;
const promotion = policyItem.promotion || {};
if (p.approved !== true) { return stop('HOLD', 'promotion_policy_not_approved'); }
if (!/^https:\/\/github\.com\/HCH725\/research-survivor\/blob\/[a-f0-9]{40}\/README\.md$/.test(String(p.source_ref || ''))) { return stop('HOLD', 'promotion_policy_source_unreadable'); }
if (p.draft_8pct_used === true) { return stop('HOLD', 'draft_8pct_policy_forbidden'); }
if (!p.thresholds || p.thresholds.cagr_min_pct !== 10 || p.thresholds.sharpe_min !== 1.0) { return stop('HOLD', 'promotion_thresholds_not_authoritative'); }
if (p.evaluation_period_defined !== true || p.cost_basis_defined !== true) { return stop('HOLD', 'evaluation_basis_undefined'); }
if (!isText(p.evaluation_unit)) { return stop('HOLD', 'evaluation_unit_undefined'); }
if (!isText(promotion.survivor_id) || !/^[a-z0-9][a-z0-9-]*$/.test(promotion.survivor_id)) { return stop('HOLD', 'promotion_identity_missing'); }
if (!isText(promotion.survivor_version)) { return stop('HOLD', 'promotion_version_missing'); }
const o = state.oos_ready || {};
const m = o.metrics || {};
const refs = o.evidence_refs || {};
const unreadable = ['oos_manifest', 'metrics', 'portfolio_report', 'trades', 'equity'].filter((key) => !isText(refs[key]));
if (unreadable.length > 0) { return stop('HOLD', 'oos_evidence_refs_unreadable:' + unreadable.join(',')); }
if (typeof m.cagr_pct !== 'number' || typeof m.sharpe !== 'number') { return stop('HOLD', 'oos_metrics_not_numeric'); }
if (!(m.trades > 0)) { return stop('HOLD', 'oos_trades_missing'); }
const evaluation = {
  cagr_pct: m.cagr_pct,
  sharpe: m.sharpe,
  cagr_min_pct: p.thresholds.cagr_min_pct,
  sharpe_min: p.thresholds.sharpe_min,
  evaluation_unit: p.evaluation_unit,
  evaluation_period: o.evaluation_period
};
const carry = Object.assign({}, state, {
  promotion: { survivor_id: promotion.survivor_id, survivor_version: promotion.survivor_version },
  policy: p,
  evaluation: evaluation
});
if (m.cagr_pct >= p.thresholds.cagr_min_pct && m.sharpe >= p.thresholds.sharpe_min) {
  return [{ json: Object.assign({}, carry, { route: 'PERF_PASS' }) }];
}
return [{ json: Object.assign({}, carry, { route: 'REJECT', reason: 'performance_below_policy' }) }];

// Boundary fixture. It represents the existing Qlib replay readback. This
// workflow does not build a new Qlib runner. A live replay readback replaces
// this node.
return [{ json: {
  payload_kind: 'qlib_replay',
  replay: {
    status: 'QLIB_REPLAY_PASS',
