// write exists yet. Tests override this node to model retry and mismatch
// outcomes. The fixture derives a matching row from the plan.
const x = $input.first().json;
const row = Object.assign({}, x.sheets.columns, {
  registry_sync_status: 'SYNCED',
  registry_last_synced_utc: '2026-10-15T09:20:00Z'
});
return [{ json: Object.assign({}, x, {
  payload_kind: 'sheets_write_result',
  write_result: {
    mode: 'upsert_by_key',
    attempt: 1,
    max_attempts: 3,
    outcome: 'upsert_ok',
    key: { survivor_id: row.survivor_id, survivor_version: row.survivor_version },
    synced_at_utc: '2026-10-15T09:20:00Z',
    rows_after: [row]
  }
}) }];

// Node12 Sheets ACK gate. The write happens only after the verified merge. The
// readback must return the same key with the same identity, hash, run ids and
// sync status. A mismatch is ERROR. A write failure retries the same key in a
// bounded loop. A duplicate row for the same key is ERROR. The repository is
// never rolled back.
const inItems = $input.all().map((entry) => entry.json);
const planItem = inItems.filter((row) => row && row.payload_kind === 'sheets_plan')[0];
const writeItem = inItems.filter((row) => row && row.payload_kind === 'sheets_write_result')[0];
const carr = planItem || {};
const stop = (route, reason, extra) => [{ json: Object.assign({}, carr, extra || {}, { route: route, reason: reason }) }];
if (!planItem || !writeItem) { return stop('ERROR', 'sheets_state_missing'); }
const w = writeItem.write_result || {};
const key = planItem.sheets.key;
const keyOf = (row) => key.map((field) => String(row ? row[field] : '')).join('\u0001');
const keyValue = keyOf(planItem.sheets.columns);
const outcome = String(w.outcome || '');
if (outcome !== 'upsert_ok') {
  const attempt = Number(w.attempt);
  const max = Number(w.max_attempts);
  if (!(attempt >= 1) || !(max >= 1) || attempt >= max) {
    return stop('ERROR', 'sheet_retry_exhausted', { retry: { same_key: true, attempts: attempt, max_attempts: max, rollback_repo: false } });
  }
  return stop('RETRY', 'sheet_write_' + outcome, { retry: { same_key: true, next_attempt: attempt + 1, max_attempts: max, duplicate_allowed: false, rollback_repo: false } });
}
const rows = (Array.isArray(w.rows_after) ? w.rows_after : []).filter((row) => keyOf(row) === keyValue);
if (rows.length === 0) { return stop('ERROR', 'readback_row_missing'); }
if (rows.length > 1) { return stop('ERROR', 'duplicate_rows_forbidden'); }
const row = rows[0];
const expect = planItem.sheets.columns;
const fields = ['survivor_git_commit', 'full_config_sha256', 'is_run_id', 'oos_run_id', 'is_window_hash', 'oos_window_hash', 'qlib_report_uri'];
for (const field of fields) {
  if (expect[field] === undefined) { continue; }
  if (row[field] !== expect[field]) { return stop('ERROR', 'readback_mismatch:' + field); }
}
if (row.registry_sync_status !== 'SYNCED') { return stop('ERROR', 'readback_sync_status_not_synced'); }
if (typeof row.registry_last_synced_utc !== 'string' || row.registry_last_synced_utc.length === 0) { return stop('ERROR', 'readback_sync_time_missing'); }
if (String(w.synced_at_utc || '') !== row.registry_last_synced_utc) { return stop('ERROR', 'readback_sync_time_mismatch'); }
return [{ json: Object.assign({}, planItem, {
  route: 'SHEETS_ACK',
  sheets_ack: {
    status: 'SHEETS_ACK',
    spreadsheet_id: planItem.sheets.spreadsheet_id,
    tab: planItem.sheets.tab,
    survivor_id: row.survivor_id,
    survivor_version: row.survivor_version,
    survivor_git_commit: row.survivor_git_commit,
    full_config_sha256: row.full_config_sha256,
    is_run_id: row.is_run_id,
    oos_run_id: row.oos_run_id,
    registry_sync_status: row.registry_sync_status,
    synced_at_utc: row.registry_last_synced_utc
  }
}) }];

// The Node13 boundary payload. Node12 stops here. It does not call Hummingbot.
// It does no parity and no certification. The HB status stays PENDING.
const x = $input.first().json;
if (x.route !== 'SHEETS_ACK') { return [{ json: { route: 'NEEDS_REVIEW', reason: 'sheets_not_acked:' + x.route } }]; }
const m = x.merge;
const rec = m.record || {};
const fm = m.frontmatter || {};
return [{ json: {
  payload_kind: 'node13_boundary',
  route: 'NODE13_BOUNDARY_READY',
  node13: {
    survivor_repository_url: 'https://github.com/HCH725/research-survivor',
    survivor_strategy_path: m.path,
    survivor_git_commit: m.merge_commit_sha,
    survivor_id: m.survivor_id,
    survivor_version: m.survivor_version,
    strategy_sha: fm.strategy_sha,
    frozen_version_sha: rec.frozen_version_sha,
    effective_config_hash: rec.full_config_sha256,
    full_config_snapshot_uri: rec.full_config_snapshot_uri,
    is_run_id: rec.is_run_id,
    oos_run_id: rec.oos_run_id,
    is_window_hash: rec.is_window_hash,
    oos_window_hash: rec.oos_window_hash,
    data_snapshot: rec.data_snapshot,
    cost_model: rec.cost_model,
    hummingbot_validation_status: 'PENDING',
    hb_certified: false,
    sheets: {
      spreadsheet_id: x.sheets.spreadsheet_id,
      tab: x.sheets.tab,
      registry_sync_status: 'SYNCED',
      registry_last_synced_utc: x.sheets_ack.synced_at_utc
    },
    note: 'Node12 stops here. No Hummingbot call, no parity, no certificate.'
  }
} }];
